import React, { useEffect, useMemo, useState } from 'react';
import {
  SafeAreaView, View, Text, ScrollView, Pressable, TextInput, StyleSheet,
  StatusBar, Modal, Alert, KeyboardAvoidingView, Platform
} from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { Ionicons, MaterialCommunityIcons } from '@expo/vector-icons';

const STORE = 'levelup-v3';
const C = {
  bg:'#F4F6FF', surface:'#FFFFFF', surface2:'#EEF0FF', surface3:'#E2E7FF',
  line:'#DCE2F4', text:'#20264A', muted:'#68708E', faint:'#929AB5',
  purple:'#8057F5', purple2:'#6840E8', cyan:'#24BDE0', mint:'#20C997',
  gold:'#F2B632', red:'#F05B83', orange:'#FF914D'
};
const ACCENTS = ['#8B70FF','#55D8F2','#62E6BD','#FFAA68','#FF718B','#F2C45C'];
const AVATARS = ['rocket','gamepad-variant','cat','robot','lightning-bolt','controller-classic','sword-cross','star-four-points'];
const CATEGORIES = [
  {id:'study',label:'Estudos',icon:'book-open-variant',color:'#8B70FF'},
  {id:'health',label:'Saúde',icon:'heart-pulse',color:'#62E6BD'},
  {id:'routine',label:'Rotina',icon:'calendar-check',color:'#55D8F2'},
  {id:'creative',label:'Criatividade',icon:'palette-outline',color:'#FFAA68'},
  {id:'personal',label:'Pessoal',icon:'star-four-points',color:'#F2C45C'},
  {id:'other',label:'Outro',icon:'target',color:'#FF718B'}
];
const initial = {
  profile:{name:'Player',handle:'player',bio:'Construindo minha melhor versão, uma missão por vez.',avatar:'rocket',accent:C.purple},
  xp:0, streak:0, lastActive:'', missions:[], friends:[], challenges:[], completedDates:[], createdAt:new Date().toISOString()
};
const todayKey = () => { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
const makeId = () => `${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
const categoryOf = id => CATEGORIES.find(c=>c.id===id)||CATEGORIES[5];

export default function App(){
  const [data,setData]=useState(initial);
  const [ready,setReady]=useState(false);
  const [tab,setTab]=useState('home');
  const [modal,setModal]=useState(null);
  const [editing,setEditing]=useState(null);
  const [missionForm,setMissionForm]=useState({title:'',description:'',category:'study',xp:'25'});
  const [profileForm,setProfileForm]=useState(initial.profile);
  const [challengeForm,setChallengeForm]=useState({title:'',description:'',days:'7'});
  const [query,setQuery]=useState('');
  const [filter,setFilter]=useState('all');

  useEffect(()=>{(async()=>{try{const raw=await AsyncStorage.getItem(STORE);if(raw){const parsed=JSON.parse(raw);if(parsed&&typeof parsed==='object'){const oldProfile=parsed.profile&&typeof parsed.profile==='object'?parsed.profile:{};setData({...initial,...parsed,xp:Number.isFinite(Number(parsed.xp))?Math.max(0,Number(parsed.xp)):0,streak:Number.isFinite(Number(parsed.streak))?Math.max(0,Number(parsed.streak)):0,missions:Array.isArray(parsed.missions)?parsed.missions.filter(m=>m&&typeof m==='object').map(m=>({...m,id:String(m.id||makeId()),title:String(m.title||'Missão'),description:String(m.description||''),category:CATEGORIES.some(c=>c.id===m.category)?m.category:'other',xp:Math.max(5,Math.min(100,Number(m.xp)||25)),done:Boolean(m.done),date:String(m.date||todayKey())})):[],challenges:Array.isArray(parsed.challenges)?parsed.challenges.filter(ch=>ch&&typeof ch==='object').map(ch=>({...ch,id:String(ch.id||makeId()),title:String(ch.title||'Desafio'),description:String(ch.description||''),days:Math.max(1,Math.min(30,Number(ch.days)||7)),done:Boolean(ch.done)})):[],completedDates:Array.isArray(parsed.completedDates)?parsed.completedDates:[],friends:Array.isArray(parsed.friends)?parsed.friends:[],profile:{...initial.profile,...oldProfile,name:typeof oldProfile.name==='string'&&oldProfile.name.trim()?oldProfile.name:'Player',handle:typeof oldProfile.handle==='string'?oldProfile.handle:'player',bio:typeof oldProfile.bio==='string'?oldProfile.bio:initial.profile.bio}});}}}catch(e){console.log('Load error',e);}finally{setReady(true);}})();},[]);
  useEffect(()=>{if(ready) AsyncStorage.setItem(STORE,JSON.stringify(data)).catch(e=>console.log('Save error',e));},[data,ready]);

  const completed=data.missions.filter(m=>m.done).length;
  const level=Math.floor(data.xp/500)+1;
  const inLevel=data.xp%500;
  const progress=inLevel/500;
  const todayMissions=data.missions.filter(m=>m.date===todayKey());
  const activeMissions=data.missions.filter(m=>!m.done);
  const filteredMissions=useMemo(()=>data.missions.filter(m=>{
    const match=(m.title+' '+m.description).toLowerCase().includes(query.toLowerCase());
    const f=filter==='all'||(filter==='done'&&m.done)||(filter==='active'&&!m.done)||filter===m.category;
    return match&&f;
  }),[data.missions,query,filter]);
  const earned=useMemo(()=>[
    {id:'first',title:'Primeiro passo',desc:'Conclua sua primeira missão.',icon:'flag-checkered',ok:completed>=1},
    {id:'five',title:'Em movimento',desc:'Conclua 5 missões.',icon:'fire',ok:data.missions.filter(m=>m.done).length>=5},
    {id:'xp',title:'Caçador de XP',desc:'Acumule 500 XP.',icon:'lightning-bolt',ok:data.xp>=500},
    {id:'streak',title:'Consistência',desc:'Mantenha uma ofensiva de 3 dias.',icon:'fire',ok:data.streak>=3},
    {id:'creator',title:'Mente estratégica',desc:'Crie 5 missões.',icon:'lightbulb-on',ok:data.missions.length>=5},
    {id:'challenge',title:'Mente estratégica',desc:'Crie seu primeiro desafio.',icon:'trophy',ok:data.challenges.length>=1}
  ],[completed,data.missions,data.xp,data.streak,data.challenges]);

  function update(patch){setData(old=>({...old,...patch}));}
  function openNewMission(){setEditing(null);setMissionForm({title:'',description:'',category:'study',xp:'25'});setModal('mission');}
  function openEditMission(m){setEditing(m.id);setMissionForm({title:m.title,description:m.description,category:m.category,xp:String(m.xp)});setModal('mission');}
  function saveMission(){
    const title=missionForm.title.trim(), description=missionForm.description.trim(), xp=Math.max(5,Math.min(100,Number(missionForm.xp)||25));
    if(!title){Alert.alert('Falta o nome','Dê um título para sua missão.');return;}
    if(!description){Alert.alert('Conte a missão','Escreva o que você precisa fazer. Assim fica mais fácil lembrar do objetivo.');return;}
    if(editing){setData(old=>{const previous=old.missions.find(m=>m.id===editing);const delta=previous?.done?xp-previous.xp:0;return {...old,xp:Math.max(0,old.xp+delta),missions:old.missions.map(m=>m.id===editing?{...m,title,description,category:missionForm.category,xp}:m)};});}
    else{setData(old=>({...old,missions:[{id:makeId(),title,description,category:missionForm.category,xp,done:false,date:todayKey(),createdAt:new Date().toISOString()},...old.missions]}));}
    setModal(null);
  }
  function deleteMission(id){Alert.alert('Excluir missão?','Essa missão será removida do seu histórico.',[{text:'Cancelar',style:'cancel'},{text:'Excluir',style:'destructive',onPress:()=>{const m=data.missions.find(x=>x.id===id);setData(old=>({...old,missions:old.missions.filter(x=>x.id!==id),xp:Math.max(0,old.xp-(m?.done?m.xp:0))}));setModal(null);}}]);}
  function toggleMission(id){
    const m=data.missions.find(x=>x.id===id);if(!m)return;
    const done=!m.done, today=todayKey();
    setData(old=>{
      let dates=[...old.completedDates]; if(done&&!dates.includes(today))dates.push(today);
      const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);const y=`${yesterday.getFullYear()}-${String(yesterday.getMonth()+1).padStart(2,'0')}-${String(yesterday.getDate()).padStart(2,'0')}`;
      const streak=done?(old.lastActive===today?old.streak:old.lastActive===y?old.streak+1:1):old.streak;
      return {...old,missions:old.missions.map(x=>x.id===id?{...x,done,completedAt:done?new Date().toISOString():null}:x),xp:Math.max(0,old.xp+(done?m.xp:-m.xp)),streak,lastActive:done?today:old.lastActive,completedDates:dates};
    });
  }
  function saveProfile(){const name=profileForm.name.trim(),handle=profileForm.handle.replace(/^@/,'').trim().replace(/\s/g,'').toLowerCase()||'player';if(!name){Alert.alert('Nome obrigatório','Escolha como seu perfil será exibido.');return;}setData(old=>({...old,profile:{...profileForm,name,handle}}));setModal(null);}
  function createChallenge(){if(!challengeForm.title.trim()){Alert.alert('Dê um nome','Todo desafio precisa de um objetivo.');return;}update({challenges:[{id:makeId(),title:challengeForm.title.trim(),description:challengeForm.description.trim()||'Seu compromisso de evolução.',days:Math.max(1,Math.min(30,Number(challengeForm.days)||7)),createdAt:todayKey(),done:false},...data.challenges]});setChallengeForm({title:'',description:'',days:'7'});setModal(null);}
  function toggleChallenge(id){setData(old=>({...old,challenges:old.challenges.map(ch=>ch.id===id?{...ch,done:!ch.done}:ch)}));}
  function resetAll(){Alert.alert('Reiniciar LevelUp?','Isso apaga missões, XP, desafios e personalização salvos neste aparelho.',[{text:'Cancelar',style:'cancel'},{text:'Reiniciar',style:'destructive',onPress:()=>{setData(initial);setTab('home');setModal(null);}}]);}

  if(!ready)return <SafeAreaView style={s.safe}><View style={s.loading}><View style={s.logo}><MaterialCommunityIcons name="arrow-up-bold" size={28} color="#fff"/></View><Text style={s.brand}>LEVELUP</Text><Text style={s.muted}>Preparando sua jornada...</Text></View></SafeAreaView>;
  const accent=data.profile.accent||C.purple;
  return <SafeAreaView style={s.safe}>
    <StatusBar barStyle="dark-content" backgroundColor={C.bg}/>
    <View style={s.appNew}>
      <ScrollView contentContainerStyle={s.scrollNew} showsVerticalScrollIndicator={false} keyboardShouldPersistTaps="handled">
        <View style={s.brandBar}><View style={s.brandMark}><MaterialCommunityIcons name="arrow-up-bold" size={20} color="#FFFFFF"/></View><Text style={s.brandNew}>LEVELUP</Text><View style={{flex:1}}/><Pressable onPress={()=>setTab('profile')} style={s.headerBell}><Ionicons name="notifications-outline" size={20} color="#D9D6F2"/></Pressable><Pressable onPress={()=>setTab('profile')} style={s.headerPlayer}><MaterialCommunityIcons name={data.profile.avatar||'rocket'} size={19} color="#FFFFFF"/></Pressable></View>
        {tab==='home'&&<>
          <View style={s.homeTopLine}><View><Text style={s.homeEyebrow}>SUA JORNADA · SEU PRÓXIMO NÍVEL</Text><Text style={s.homeGreeting}>Olá, {data.profile.name.split(' ')[0]}!</Text></View><Pressable onPress={()=>setTab('profile')} style={s.homeAvatar}><MaterialCommunityIcons name={data.profile.avatar||'rocket'} size={23} color="#FFFFFF"/></Pressable></View>
          <View style={s.adventureHero}>
            <View style={s.heroStars}><View style={s.starDot}/><View style={s.starDotSmall}/><View style={s.starDot}/></View>
            <View style={s.heroCopy}><View style={s.heroBadge}><MaterialCommunityIcons name="sword-cross" size={12} color="#FFE08A"/><Text style={s.heroBadgeText}>SUA AVENTURA</Text></View><Text style={s.adventureTitle}>Cada missão te leva mais longe.</Text><Text style={s.adventureSubtitle}>Construa hábitos. Ganhe XP. Desbloqueie seu potencial.</Text><Pressable style={s.heroAction} onPress={openNewMission}><Text style={s.heroActionText}>Nova missão</Text><Ionicons name="arrow-forward" size={15} color="#17102F"/></Pressable></View>
            <View style={s.heroArtwork}><View style={s.heroPlanet}/><View style={s.heroPlanetRing}/><View style={s.heroBadgeGem}><MaterialCommunityIcons name="trophy" size={43} color="#FFE27A"/></View><View style={s.heroSpark}><MaterialCommunityIcons name="star-four-points" size={17} color="#FFFFFF"/></View><View style={s.heroSparkTwo}><MaterialCommunityIcons name="star-four-points" size={12} color="#74F0FF"/></View></View>
          </View>
          <View style={s.levelCardNew}>
            <View style={s.levelCardTop}><View style={s.levelEmblem}><MaterialCommunityIcons name="shield-star" size={30} color="#FFE08A"/></View><View style={{flex:1}}><Text style={s.levelOverline}>SEU RANK ATUAL</Text><Text style={s.levelNameNew}>Nível {level} · {level<3?'Aprendiz':level<6?'Explorador':level<10?'Veterano':'Lenda'}</Text></View><View style={s.xpPill}><MaterialCommunityIcons name="lightning-bolt" size={14} color="#FFE08A"/><Text style={s.xpPillText}>{data.xp} XP</Text></View></View>
            <View style={s.progressTrackNew}><View style={[s.progressFillNew,{width:`${progress*100}%`}]}/></View><View style={s.progressLabels}><Text style={s.progressCaption}>{inLevel} / 500 XP</Text><Text style={s.progressCaption}>Faltam {500-inLevel} XP</Text></View>
          </View>
          <View style={s.statTiles}><View style={[s.statTile,{backgroundColor:'#4B2B82'}]}><View style={[s.statIcon,{backgroundColor:'#FF9B5424'}]}><MaterialCommunityIcons name="fire" color="#FFAA68" size={21}/></View><Text style={s.statNumber}>{data.streak}</Text><Text style={s.statCaption}>DIAS DE OFENSIVA</Text></View><View style={[s.statTile,{backgroundColor:'#155477'}]}><View style={[s.statIcon,{backgroundColor:'#55D8F224'}]}><MaterialCommunityIcons name="check-decagram" color="#55D8F2" size={21}/></View><Text style={s.statNumber}>{completed}</Text><Text style={s.statCaption}>MISSÕES FEITAS</Text></View><View style={[s.statTile,{backgroundColor:'#70405F'}]}><View style={[s.statIcon,{backgroundColor:'#FFD36B24'}]}><MaterialCommunityIcons name="trophy" color="#FFD36B" size={21}/></View><Text style={s.statNumber}>{earned.filter(a=>a.ok).length}</Text><Text style={s.statCaption}>CONQUISTAS</Text></View></View>
          <View style={s.sectionHeaderNew}><View><Text style={s.sectionTitleNew}>Missões de hoje</Text><Text style={s.sectionSubNew}>{todayMissions.filter(m=>m.done).length} de {todayMissions.length} concluídas</Text></View><Pressable onPress={()=>setTab('missions')} style={s.seeAll}><Text style={s.seeAllText}>Ver todas</Text><Ionicons name="arrow-forward" size={13} color="#A995FF"/></Pressable></View>
          {todayMissions.length?todayMissions.slice(0,4).map(m=><MissionCard key={m.id} mission={m} onToggle={()=>toggleMission(m.id)} onOpen={()=>openEditMission(m)} accent={accent}/>):<View style={s.emptyQuest}><View style={s.emptyQuestIcon}><MaterialCommunityIcons name="flag-checkered" size={30} color="#A995FF"/></View><Text style={s.emptyTitle}>Sua próxima conquista começa aqui</Text><Text style={s.emptyText}>Escolha uma meta simples e transforme seu dia em progresso.</Text><Pressable style={s.heroAction} onPress={openNewMission}><Text style={s.heroActionText}>Criar primeira missão</Text><Ionicons name="arrow-forward" size={15} color="#17102F"/></Pressable></View>}
          <View style={s.nextReward}><View style={s.rewardIcon}><MaterialCommunityIcons name="medal" size={25} color="#FFD36B"/></View><View style={{flex:1}}><Text style={s.rewardTitle}>Próxima recompensa</Text><Text style={s.rewardSubtitle}>Alcance o nível {level+1} e continue evoluindo.</Text></View><Text style={s.rewardXP}>{500-inLevel} XP</Text></View>
        </>}
        {tab==='missions'&&<>
          <View style={s.pageIntro}><Text style={s.pageEyebrow}>SEU MAPA DE PROGRESSO</Text><Text style={s.pageTitle}>Missões</Text><Text style={s.pageSubtitle}>Pequenas ações. Grandes mudanças.</Text></View>
          <View style={{backgroundColor:'#5B39C9',borderRadius:25,padding:19,marginBottom:15,overflow:'hidden',borderWidth:1.5,borderColor:'#A58AFF'}}>
            <View style={{position:'absolute',right:-22,top:-30,width:145,height:145,borderRadius:80,backgroundColor:'#A66BFF',opacity:.55}}/><View style={{position:'absolute',right:46,bottom:-44,width:110,height:110,borderRadius:60,backgroundColor:'#2CCFEA',opacity:.35}}/>
            <View style={{flexDirection:'row',alignItems:'center',gap:7,marginBottom:10}}><MaterialCommunityIcons name="map-marker-path" size={16} color="#FFE27A"/><Text style={{fontSize:9,fontWeight:'900',letterSpacing:1.5,color:'#FFE8A4'}}>CENTRAL DE MISSÕES</Text></View>
            <Text style={{fontSize:23,lineHeight:28,fontWeight:'900',color:'#FFFFFF',maxWidth:250}}>Transforme seus planos em conquistas.</Text>
            <Text style={{fontSize:11,lineHeight:17,color:'#E8DEFF',marginTop:7,maxWidth:245}}>Cada tarefa concluída aproxima você do próximo nível.</Text>
            <View style={{flexDirection:'row',gap:8,marginTop:15}}><View style={{backgroundColor:'#FFFFFF25',borderRadius:12,paddingHorizontal:11,paddingVertical:8,flexDirection:'row',alignItems:'center',gap:5}}><MaterialCommunityIcons name="lightning-bolt" color="#FFE27A" size={15}/><Text style={{fontSize:10,fontWeight:'900',color:'#FFFFFF'}}>{data.xp} XP acumulados</Text></View><View style={{backgroundColor:'#FFFFFF25',borderRadius:12,paddingHorizontal:11,paddingVertical:8,flexDirection:'row',alignItems:'center',gap:5}}><MaterialCommunityIcons name="target" color="#7DF3E0" size={15}/><Text style={{fontSize:10,fontWeight:'900',color:'#FFFFFF'}}>{data.missions.length} objetivos</Text></View></View>
          </View>
          <View style={s.missionSummaryNew}><View><Text style={s.summaryLabelNew}>PROGRESSO TOTAL</Text><Text style={s.summaryBigNew}>{completed}<Text style={s.summarySlashNew}> / {data.missions.length} missões</Text></Text></View><View style={{alignItems:'flex-end'}}><Text style={[s.summaryPercent,{color:'#FFE27A'}]}>{data.missions.length?Math.round(completed/data.missions.length*100):0}%</Text><Text style={s.smallMuted}>concluído</Text></View></View>
          <View style={{flexDirection:'row',gap:8,marginBottom:14}}>{[{n:String(data.missions.filter(m=>!m.done).length),l:'PENDENTES',c:'#FF9B55',i:'flag-outline',bg:'#713F45'},{n:String(completed),l:'CONCLUÍDAS',c:'#62E6B5',i:'check-decagram',bg:'#155B59'},{n:String(data.missions.reduce((a,m)=>a+(m.done?m.xp:0),0)),l:'XP GANHO',c:'#FFD45F',i:'lightning-bolt',bg:'#705124'}].map((x,i)=><View key={i} style={{flex:1,minHeight:79,borderRadius:17,backgroundColor:x.bg,padding:10,borderWidth:1,borderColor:x.c+'75'}}><MaterialCommunityIcons name={x.i} size={17} color={x.c}/><Text style={{fontSize:19,fontWeight:'900',color:'#FFFFFF',marginTop:4}}>{x.n}</Text><Text style={{fontSize:7,fontWeight:'900',letterSpacing:.7,color:x.c,marginTop:2}}>{x.l}</Text></View>)}</View>
          <View style={s.searchBoxNew}><Ionicons name="search" color={C.muted} size={19}/><TextInput value={query} onChangeText={setQuery} placeholder="Buscar missão..." placeholderTextColor={C.faint} style={s.searchInput}/>{query.length>0&&<Pressable onPress={()=>setQuery('')}><Ionicons name="close-circle" size={18} color={C.muted}/></Pressable>}</View>
          <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.chipsNew}>{[{id:'all',label:'Todas'},{id:'active',label:'Pendentes'},{id:'done',label:'Concluídas'},...CATEGORIES].map(f=><Pressable key={f.id} onPress={()=>setFilter(f.id)} style={[s.chipNew,filter===f.id&&s.chipSelectedNew]}><Text style={[s.chipTextNew,filter===f.id&&{color:'#FFFFFF'}]}>{f.label}</Text></Pressable>)}</ScrollView>
          {filteredMissions.length?filteredMissions.map(m=><MissionCard key={m.id} mission={m} onToggle={()=>toggleMission(m.id)} onOpen={()=>openEditMission(m)} accent={accent}/>):<View style={s.empty}><View style={s.emptyIcon}><MaterialCommunityIcons name="clipboard-text-outline" size={27} color={accent}/></View><Text style={s.emptyTitle}>Nada por aqui ainda</Text><Text style={s.emptyText}>Crie uma missão com título, descrição e recompensa de XP.</Text></View>}
          <Pressable style={[s.primaryBtn,{backgroundColor:accent,marginTop:14}]} onPress={openNewMission}><Ionicons name="add" size={19} color="#fff"/><Text style={s.primaryText}>Nova missão</Text></Pressable>
        </>}
        {tab==='challenges'&&<>
          <View style={s.pageIntro}><Text style={s.pageEyebrow}>SEU COMPROMISSO</Text><Text style={s.pageTitle}>Desafios</Text><Text style={s.pageSubtitle}>Metas com prazo para sair do papel.</Text></View>
          <View style={s.challengeHero}><View style={s.challengeHeroIcon}><MaterialCommunityIcons name="trophy-award" size={28} color="#FFE28A"/></View><View style={{flex:1}}><Text style={s.challengeHeroTitle}>Assuma um desafio.</Text><Text style={s.challengeHeroText}>Escolha um objetivo e acompanhe sua consistência.</Text></View></View>
          <View style={s.sectionHeaderNew}><View><Text style={s.sectionTitleNew}>Seus desafios</Text><Text style={s.sectionSubNew}>{data.challenges.filter(ch=>ch.done).length} de {data.challenges.length} concluídos</Text></View><Pressable onPress={()=>{setChallengeForm({title:'',description:'',days:'7'});setModal('challenge');}} style={s.seeAll}><Text style={s.seeAllText}>Criar novo</Text><Ionicons name="add" size={15} color="#A995FF"/></Pressable></View>
          {data.challenges.length?data.challenges.map(ch=><View key={ch.id} style={[s.challengeCard,ch.done&&s.challengeCardDone]}><View style={[s.challengeIcon,{backgroundColor:ch.done?'#DDF8EF':'#EEE8FF'}]}><MaterialCommunityIcons name={ch.done?'checkmark-circle':'flag-checkered'} size={23} color={ch.done?C.mint:accent}/></View><View style={{flex:1}}><Text style={s.challengeTitle}>{ch.title}</Text><Text style={s.challengeDescription}>{ch.description}</Text><Text style={s.challengeMeta}>{ch.days} DIAS · {ch.done?'CONCLUÍDO':'EM ANDAMENTO'}</Text></View><Pressable onPress={()=>toggleChallenge(ch.id)} style={[s.challengeToggle,ch.done&&s.challengeToggleDone]}><Ionicons name={ch.done?'checkmark-done':'checkmark'} size={19} color={ch.done?'#FFFFFF':accent}/></Pressable></View>):<View style={s.empty}><View style={s.emptyIcon}><MaterialCommunityIcons name="trophy-outline" size={27} color={accent}/></View><Text style={s.emptyTitle}>Nenhum desafio ativo</Text><Text style={s.emptyText}>Crie seu primeiro desafio e transforme uma intenção em compromisso.</Text><Pressable style={[s.primaryBtn,{backgroundColor:accent,marginTop:14}]} onPress={()=>{setChallengeForm({title:'',description:'',days:'7'});setModal('challenge');}}><Ionicons name="add" size={18} color="#FFFFFF"/><Text style={s.primaryText}>Criar desafio</Text></Pressable></View>}
        </>}
        {tab==='profile'&&<>
          <View style={s.pageIntro}><Text style={s.pageEyebrow}>SUA IDENTIDADE</Text><Text style={s.pageTitle}>Meu perfil</Text><Text style={s.pageSubtitle}>Veja o quanto você já evoluiu.</Text></View>
          <View style={{backgroundColor:'#B64F83',borderRadius:25,padding:17,marginBottom:14,overflow:'hidden',borderWidth:1.5,borderColor:'#FF9BC5'}}><View style={{position:'absolute',right:-20,top:-43,width:145,height:145,borderRadius:75,backgroundColor:'#FF9F70',opacity:.42}}/><View style={{position:'absolute',right:76,bottom:-52,width:120,height:120,borderRadius:65,backgroundColor:'#795BFF',opacity:.45}}/><View style={{flexDirection:'row',alignItems:'center',gap:8}}><MaterialCommunityIcons name="crown" color="#FFE27A" size={18}/><Text style={{fontSize:9,fontWeight:'900',letterSpacing:1.3,color:'#FFE8B0'}}>CARTÃO DE JOGADOR</Text></View><Text style={{fontSize:22,fontWeight:'900',color:'#FFFFFF',marginTop:9}}>Sua jornada. Sua história.</Text><Text style={{fontSize:11,color:'#FFE5F1',marginTop:5}}>Personalize seu espaço e mostre sua evolução.</Text><View style={{flexDirection:'row',alignItems:'center',gap:7,marginTop:13}}><View style={{backgroundColor:'#FFFFFF25',borderRadius:11,paddingHorizontal:10,paddingVertical:7}}><Text style={{fontSize:9,fontWeight:'900',color:'#FFFFFF'}}>NÍVEL {level}</Text></View><View style={{backgroundColor:'#FFFFFF25',borderRadius:11,paddingHorizontal:10,paddingVertical:7}}><Text style={{fontSize:9,fontWeight:'900',color:'#FFFFFF'}}>{data.xp} XP</Text></View></View></View>
          <View style={s.profileCardNew}><View style={[s.profileAvatar,{backgroundColor:accent+'25',borderColor:accent+'90'}]}><MaterialCommunityIcons name={data.profile.avatar||'rocket'} size={42} color={accent}/></View><Text style={s.profileName}>{data.profile.name}</Text><Text style={s.profileHandle}>@{data.profile.handle}</Text><Text style={s.profileBio}>{data.profile.bio||'Sem descrição ainda.'}</Text><View style={s.profileStats}><ProfileStat value={String(level)} label="NÍVEL"/><ProfileStat value={String(data.xp)} label="XP TOTAL"/><ProfileStat value={String(completed)} label="CONCLUÍDAS"/></View><Pressable style={[s.secondaryBtn,{borderColor:accent+'70'}]} onPress={()=>{setProfileForm({...data.profile});setModal('profile');}}><Ionicons name="create-outline" color={accent} size={17}/><Text style={[s.secondaryText,{color:accent}]}>Editar perfil</Text></Pressable></View>
          <View style={{backgroundColor:'#6542B5',borderRadius:21,padding:16,marginBottom:16,borderWidth:1.3,borderColor:'#A88AFF'}}><View style={{flexDirection:'row',alignItems:'center',justifyContent:'space-between'}}><View><Text style={{fontSize:9,fontWeight:'900',letterSpacing:1.2,color:'#E7D9FF'}}>COLEÇÃO DE TROFÉUS</Text><Text style={{fontSize:25,fontWeight:'900',color:'#FFFFFF',marginTop:5}}>{earned.filter(a=>a.ok).length}<Text style={{fontSize:13,color:'#D7C8FF'}}> / {earned.length}</Text></Text><Text style={{fontSize:10,color:'#E7DEFF',marginTop:2}}>conquistas desbloqueadas</Text></View><View style={{width:61,height:61,borderRadius:20,backgroundColor:'#F4B84E',alignItems:'center',justifyContent:'center'}}><MaterialCommunityIcons name="trophy-award" size={35} color="#FFFFFF"/></View></View><View style={{height:9,backgroundColor:'#3A2B76',borderRadius:9,overflow:'hidden',marginTop:13}}><View style={{height:'100%',width:`${earned.length?earned.filter(a=>a.ok).length/earned.length*100:0}%`,backgroundColor:'#FFE17A',borderRadius:9}}/></View></View>
          <View style={s.sectionHeader}><View><Text style={s.sectionTitle}>Conquistas</Text><Text style={s.sectionSub}>Continue completando missões para desbloquear novas medalhas.</Text></View><MaterialCommunityIcons name="medal" size={22} color={C.gold}/></View>
          <View style={s.achievementGrid}>{earned.map(a=><View key={a.id} style={[s.achievement,{opacity:a.ok?1:.45,borderColor:a.ok?C.gold+'70':C.line}]}><View style={[s.achievementIcon,{backgroundColor:a.ok?C.gold+'20':C.surface3}]}><MaterialCommunityIcons name={a.icon} size={24} color={a.ok?C.gold:C.faint}/></View><Text style={s.achievementTitle}>{a.title}</Text><Text style={s.achievementDesc}>{a.desc}</Text><Text style={[s.achievementStatus,{color:a.ok?C.mint:C.faint}]}>{a.ok?'DESBLOQUEADA':'BLOQUEADA'}</Text></View>)}</View>
          <View style={s.sectionHeader}><Text style={s.sectionTitle}>Configurações</Text></View>
          <Pressable style={s.settingRow} onPress={resetAll}><View style={[s.settingIcon,{backgroundColor:C.red+'18'}]}><Ionicons name="refresh-outline" color={C.red} size={19}/></View><View style={{flex:1}}><Text style={[s.missionTitle,{color:C.red}]}>Reiniciar dados</Text><Text style={s.bodySmall}>Apaga o progresso salvo neste aparelho</Text></View><Ionicons name="chevron-forward" color={C.muted} size={18}/></Pressable>
          <Text style={s.version}>LEVELUP · BUILD 2.1 · FEITO PARA EVOLUIR</Text>
        </>}
      </ScrollView>
      <View style={s.navNew}>
        <NavItem icon="home-outline" activeIcon="home" label="Início" active={tab==='home'} onPress={()=>setTab('home')} accent={accent}/>
        <NavItem icon="checkbox-outline" activeIcon="checkbox" label="Missões" active={tab==='missions'} onPress={()=>setTab('missions')} accent={accent}/>
        <Pressable style={[s.navAdd,{backgroundColor:accent}]} onPress={openNewMission}><Ionicons name="add" size={28} color="#fff"/></Pressable>
        <NavItem icon="trophy-outline" activeIcon="trophy" label="Desafios" active={tab==='challenges'} onPress={()=>setTab('challenges')} accent={accent}/>
        <NavItem icon="person-outline" activeIcon="person" label="Perfil" active={tab==='profile'} onPress={()=>setTab('profile')} accent={accent}/>
      </View>
    </View>
    <Modal visible={!!modal} transparent animationType="slide" onRequestClose={()=>setModal(null)}>
      <View style={s.modalBackdrop}><KeyboardAvoidingView behavior={Platform.OS==='ios'?'padding':undefined} style={s.modalKeyboard}><View style={s.modalSheet}>
        <View style={s.modalHeader}><View><Text style={s.modalEyebrow}>{modal==='mission'?'CONSTRUA SEU PROGRESSO':modal==='profile'?'SUA IDENTIDADE':'SEU PRÓXIMO OBJETIVO'}</Text><Text style={s.modalTitle}>{modal==='mission'?(editing?'Editar missão':'Nova missão'):modal==='profile'?'Personalizar perfil':modal==='friend'?'Adicionar amigo':'Novo desafio'}</Text></View><Pressable style={s.closeBtn} onPress={()=>setModal(null)}><Ionicons name="close" size={21} color={C.text}/></Pressable></View>
        <ScrollView showsVerticalScrollIndicator={false} keyboardShouldPersistTaps="handled">
          {modal==='mission'&&<>
            <Field label="NOME DA MISSÃO" value={missionForm.title} onChangeText={v=>setMissionForm({...missionForm,title:v})} placeholder="Ex.: Estudar inglês por 20 minutos" maxLength={50}/>
            <Field label="DESCRIÇÃO · O QUE VOCÊ VAI FAZER?" value={missionForm.description} onChangeText={v=>setMissionForm({...missionForm,description:v})} placeholder="Descreva a tarefa com detalhes. Ex.: assistir uma aula, anotar 5 palavras novas e revisar o conteúdo." multiline maxLength={220}/>
            <Text style={s.fieldLabel}>CATEGORIA</Text><View style={s.categoryGrid}>{CATEGORIES.map(c=><Pressable key={c.id} onPress={()=>setMissionForm({...missionForm,category:c.id})} style={[s.categoryOption,missionForm.category===c.id&&{borderColor:c.color,backgroundColor:c.color+'18'}]}><MaterialCommunityIcons name={c.icon} size={19} color={c.color}/><Text style={s.categoryText}>{c.label}</Text></Pressable>)}</View>
            <Field label="RECOMPENSA EM XP (5 A 100)" value={missionForm.xp} onChangeText={v=>setMissionForm({...missionForm,xp:v.replace(/[^0-9]/g,'')})} placeholder="25" keyboardType="number-pad"/>
            <View style={s.formHint}><Ionicons name="information-circle-outline" size={17} color={C.cyan}/><Text style={s.formHintText}>Escolha uma recompensa justa para o esforço. Você ganha XP ao concluir a missão.</Text></View>
            <Pressable style={[s.primaryBtn,{backgroundColor:accent,marginTop:18}]} onPress={saveMission}><Ionicons name="checkmark" size={19} color="#fff"/><Text style={s.primaryText}>{editing?'Salvar alterações':'Criar missão'}</Text></Pressable>
            {editing&&<Pressable style={s.deleteBtn} onPress={()=>deleteMission(editing)}><Ionicons name="trash-outline" size={17} color={C.red}/><Text style={s.deleteText}>Excluir missão</Text></Pressable>}
          </>}
          {modal==='profile'&&<>
            <Text style={s.fieldLabel}>ESCOLHA SEU AVATAR</Text><View style={s.avatarGrid}>{AVATARS.map(a=><Pressable key={a} onPress={()=>setProfileForm({...profileForm,avatar:a})} style={[s.avatarOption,profileForm.avatar===a&&{borderColor:profileForm.accent,backgroundColor:profileForm.accent+'25'}]}><MaterialCommunityIcons name={a} size={24} color={profileForm.avatar===a?profileForm.accent:C.muted}/></Pressable>)}</View>
            <Field label="NOME DE EXIBIÇÃO" value={profileForm.name} onChangeText={v=>setProfileForm({...profileForm,name:v})} placeholder="Como quer ser chamado?" maxLength={24}/>
            <Field label="NOME DE USUÁRIO" value={profileForm.handle} onChangeText={v=>setProfileForm({...profileForm,handle:v.replace(/^@/,'').replace(/\s/g,'')})} placeholder="seuusuario" maxLength={18}/>
            <Field label="BIO" value={profileForm.bio} onChangeText={v=>setProfileForm({...profileForm,bio:v})} placeholder="Conte um pouco sobre seus objetivos..." multiline maxLength={100}/>
            <Text style={s.fieldLabel}>COR DE DESTAQUE</Text><View style={s.colorRow}>{ACCENTS.map(color=><Pressable key={color} onPress={()=>setProfileForm({...profileForm,accent:color})} style={[s.colorDot,{backgroundColor:color},profileForm.accent===color&&s.colorDotSelected]}>{profileForm.accent===color&&<Ionicons name="checkmark" size={17} color="#08101D"/>}</Pressable>)}</View>
            <Pressable style={[s.primaryBtn,{backgroundColor:profileForm.accent||accent,marginTop:22}]} onPress={saveProfile}><Ionicons name="save-outline" size={18} color="#fff"/><Text style={s.primaryText}>Salvar perfil</Text></Pressable>
          </>}
          {modal==='challenge'&&<><Field label="NOME DO DESAFIO" value={challengeForm.title} onChangeText={v=>setChallengeForm({...challengeForm,title:v})} placeholder="Ex.: Semana sem procrastinar"/><Field label="OBJETIVO" value={challengeForm.description} onChangeText={v=>setChallengeForm({...challengeForm,description:v})} placeholder="O que a equipe quer alcançar?" multiline/><Field label="DURAÇÃO EM DIAS (1 A 30)" value={challengeForm.days} onChangeText={v=>setChallengeForm({...challengeForm,days:v.replace(/[^0-9]/g,'')})} keyboardType="number-pad"/><Pressable style={[s.primaryBtn,{backgroundColor:accent,marginTop:20}]} onPress={createChallenge}><Ionicons name="trophy" size={18} color="#fff"/><Text style={s.primaryText}>Criar desafio</Text></Pressable></>}
        </ScrollView>
      </View></KeyboardAvoidingView></View>
    </Modal>
  </SafeAreaView>;
}

function Field({label,value,onChangeText,placeholder,multiline,keyboardType,maxLength,secureTextEntry}){return <View style={s.fieldWrap}><Text style={s.fieldLabel}>{label}</Text><TextInput value={value} onChangeText={onChangeText} placeholder={placeholder} placeholderTextColor={C.faint} style={[s.input,multiline&&s.textarea]} multiline={multiline} textAlignVertical={multiline?'top':'center'} keyboardType={keyboardType||'default'} maxLength={maxLength} secureTextEntry={secureTextEntry} /></View>;}
function ScreenHeading({eyebrow,title,subtitle}){return <View style={s.screenHeading}><Text style={s.kicker}>{eyebrow}</Text><Text style={s.screenTitle}>{title}</Text><Text style={s.body}>{subtitle}</Text></View>;}
function QuickStat({icon,value,label,color}){return <View style={s.quickStat}><MaterialCommunityIcons name={icon} size={17} color={color}/><Text style={s.quickValue}>{value}</Text><Text style={s.quickLabel}>{label}</Text></View>;}
function ProfileStat({value,label}){return <View style={{alignItems:'center',flex:1}}><Text style={s.profileStatValue}>{value}</Text><Text style={s.profileStatLabel}>{label}</Text></View>;}
function MissionCard({mission,onToggle,onOpen,accent}){const cat=categoryOf(mission.category);return <View style={[s.missionCardNew,{borderLeftColor:cat.color,borderLeftWidth:4},mission.done&&s.missionCardDoneNew]}><Pressable style={[s.missionCatIconNew,{backgroundColor:cat.color+'35'}]} onPress={onOpen}><MaterialCommunityIcons name={cat.icon} size={23} color={cat.color}/></Pressable><Pressable style={{flex:1}} onPress={onOpen}><Text style={[s.missionTitleNew,mission.done&&s.doneText]} numberOfLines={1}>{mission.title}</Text><Text style={s.missionDescNew} numberOfLines={2}>{mission.description||'Missão pessoal'}</Text><View style={s.missionMetaNew}><Text style={[s.categoryTagNew,{color:cat.color}]}>{cat.label}</Text><View style={s.metaDividerNew}/><Text style={s.missionXPNew}>+{mission.xp} XP</Text></View></Pressable><Pressable onPress={onToggle} style={[s.completeButtonNew,mission.done&&s.completeButtonDone]}><Ionicons name={mission.done?'checkmark':'checkmark'} size={18} color={mission.done?'#071525':'#B8B1D8'}/></Pressable></View>;}
function NavItem({icon,activeIcon,label,active,onPress,accent}){return <Pressable style={[s.navItem,active&&s.navItemActive]} onPress={onPress}><Ionicons name={active?activeIcon:icon} size={22} color={active?'#FFFFFF':'#8FA3C8'}/><Text style={[s.navLabel,active&&{color:'#FFFFFF'}]}>{label}</Text></Pressable>;}

